package main

import (
	"errors"
	"fmt"
)

func half(n int) (int, error) {
	if n%2 != 0 {
		return 0, errors.New("odd number")
	}
	return n / 2, nil
}

func main() {
	if v, err := half(7); err != nil {
		fmt.Println("error:", err)
	} else {
		fmt.Println(v)
	}
}

